#[test]
fn config_defaults_builders_and_debug() {
    let c = TracingConfig::new("svc");
    assert_eq!(c.protocol, Protocol::HttpProtobuf);
    assert_eq!(c.sampler, SamplerKind::ParentBasedAlwaysOn);
    assert_eq!(c.sampler_ratio, 1.0);
    assert_eq!(
        c.propagators,
        [PropagatorKind::TraceContext, PropagatorKind::Baggage]
    );
    assert_eq!(c.batch, TraceBatchConfig::default());
    assert_eq!(c.batch.max_queue_size, 2048);
    assert_eq!(c.batch.max_export_batch_size, 512);
    assert_eq!(c.batch.scheduled_delay, Duration::from_secs(5));
    assert_eq!(c.batch.export_timeout, Duration::from_secs(30));
    assert_eq!(c.compression, Compression::Gzip);
    assert!(c.set_global);
    assert!(c.validate().is_ok());

    let c = TracingConfig::new("svc")
        .with_service_version("1.2.3")
        .with_environment("test")
        .with_resource_attribute("team", "core")
        .with_endpoint("https://user:pw@otel:4318?token=abc")
        .with_protocol(Protocol::Grpc)
        .with_header("Authorization", "Bearer s3cr3t")
        .with_header("x-tenant", "t1")
        .with_sampler(SamplerKind::TraceIdRatio, 0.5)
        .with_propagators(vec![PropagatorKind::B3])
        .with_batch(TraceBatchConfig {
            max_queue_size: 10,
            max_export_batch_size: 5,
            ..Default::default()
        })
        .with_tls(TlsConfig::default())
        .with_compression(Compression::None)
        .with_set_global(false);
    assert!(c.validate().is_ok());
    let dbg = format!("{c:?}");
    assert!(!dbg.contains("s3cr3t"), "{dbg}");
    assert!(!dbg.contains("pw@"), "{dbg}");
    assert!(dbg.contains("t1"));
    assert_eq!(c.resource_attributes["team"], "core");
}

