#[test]
fn enum_parsing() {
    for p in [Protocol::Grpc, Protocol::HttpProtobuf, Protocol::Native] {
        assert_eq!(p.as_str().parse::<Protocol>().unwrap(), p);
    }
    assert_eq!("HTTP".parse::<Protocol>().unwrap(), Protocol::HttpProtobuf);
    assert_eq!(
        "smoke".parse::<Protocol>().unwrap_err().code(),
        ErrorCode::Config
    );
    for s in [
        SamplerKind::AlwaysOn,
        SamplerKind::AlwaysOff,
        SamplerKind::TraceIdRatio,
        SamplerKind::ParentBasedAlwaysOn,
        SamplerKind::ParentBasedAlwaysOff,
        SamplerKind::ParentBasedTraceIdRatio,
    ] {
        assert_eq!(s.as_str().parse::<SamplerKind>().unwrap(), s);
    }
    assert!("sometimes".parse::<SamplerKind>().is_err());
    for p in ["tracecontext", "baggage", "b3", "b3multi", "datadog"] {
        assert_eq!(p.parse::<PropagatorKind>().unwrap().as_str(), p);
    }
    assert_eq!(
        " SW8 ".parse::<PropagatorKind>().unwrap(),
        PropagatorKind::Other("sw8".into())
    );
    assert!("".parse::<PropagatorKind>().is_err());
    let err = build_propagator(&[PropagatorKind::Other("x".into())], HashMap::new()).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Config);
}

#[test]
fn otel_value_conversion() {
    assert_eq!(otel_value(&json!("s")), Value::from("s"));
    assert_eq!(otel_value(&json!(true)), Value::Bool(true));
    assert_eq!(otel_value(&json!(3)), Value::I64(3));
    assert_eq!(otel_value(&json!(1.5)), Value::F64(1.5));
    assert_eq!(otel_value(&json!(u64::MAX)), Value::F64(u64::MAX as f64));
    assert_eq!(
        otel_value(&json!(["a", "b"])),
        Value::Array(Array::String(vec!["a".into(), "b".into()]))
    );
    assert_eq!(
        otel_value(&json!([1, 2])),
        Value::Array(Array::I64(vec![1, 2]))
    );
    assert_eq!(
        otel_value(&json!([1, 2.5])),
        Value::Array(Array::F64(vec![1.0, 2.5]))
    );
    assert_eq!(
        otel_value(&json!([true])),
        Value::Array(Array::Bool(vec![true]))
    );
    assert_eq!(otel_value(&json!([1, "a"])), Value::from("[1,\"a\"]"));
    assert_eq!(otel_value(&json!([])), Value::from("[]"));
    assert_eq!(otel_value(&json!({"a": 1})), Value::from("{\"a\":1}"));
    assert_eq!(otel_value(&json!(null)), Value::from("null"));
}

#[test]
fn native_ids_and_explicit_settings() {
    use sdk::tracing::{normalize_span_id_or_native, normalize_trace_id_or_native};
    assert_eq!(
        normalize_trace_id_or_native("0xABC").unwrap(),
        "00000000000000000000000000000abc"
    );
    assert_eq!(
        normalize_trace_id_or_native(" 2.58.17000000000000001 ").unwrap(),
        "2.58.17000000000000001"
    );
    assert_eq!(
        normalize_trace_id_or_native(&"a".repeat(40)).unwrap(),
        "a".repeat(40)
    );
    assert_eq!(
        normalize_span_id_or_native("1F").unwrap(),
        "000000000000001f"
    );
    assert_eq!(normalize_span_id_or_native("seg-1").unwrap(), "seg-1");
    for bad in ["", "  ", "0x"] {
        assert_eq!(
            normalize_trace_id_or_native(bad).map_err(|e| e.code()),
            if bad == "0x" {
                Ok("0x".to_owned())
            } else {
                Err(sdk::ErrorCode::Validation)
            },
            "{bad:?}"
        );
    }
    assert_eq!(
        normalize_trace_id_or_native("0").unwrap_err().code(),
        sdk::ErrorCode::Validation
    );

    let c = TracingConfig::new("svc");
    assert_eq!(c.explicit_protocol(), None);
    assert_eq!(c.explicit_propagators(), None);
    let c = c
        .with_protocol(Protocol::HttpProtobuf)
        .with_propagators(vec![PropagatorKind::TraceContext, PropagatorKind::Baggage]);
    assert_eq!(c.explicit_protocol(), Some(Protocol::HttpProtobuf));
    assert_eq!(c.explicit_propagators().map(<[_]>::len), Some(2));
    let mut c = TracingConfig::new("svc");
    c.protocol = Protocol::Grpc;
    c.propagators = vec![PropagatorKind::B3];
    assert_eq!(c.explicit_protocol(), Some(Protocol::Grpc));
    assert_eq!(c.explicit_propagators(), Some(&[PropagatorKind::B3][..]));
}

