fn span(id: &str, parent: Option<&str>, name: &str, start: u64, end: u64) -> Span {
    Span {
        trace_id: "4bf92f3577b34da6a3ce929d0e0e4736".into(),
        span_id: id.into(),
        parent_span_id: parent.map(Into::into),
        name: name.into(),
        kind: SpanKind::Internal,
        service_name: "svc".into(),
        start_micros: start,
        end_micros: end,
        duration_micros: end - start,
        status: SpanStatus::default(),
        attributes: Default::default(),
        events: vec![],
        links: vec![],
    }
}

#[test]
fn sorting_trees_and_summaries() {
    let spans = vec![
        span(
            "000000000000000c",
            Some("000000000000000a"),
            "child-b",
            20,
            30,
        ),
        span(
            "000000000000000b",
            Some("000000000000000a"),
            "child-a",
            10,
            20,
        ),
        span("000000000000000a", None, "root", 10, 50),
        span("000000000000000d", Some("ffffffffffffffff"), "orphan", 5, 6),
        span(
            "000000000000000e",
            Some("000000000000000e"),
            "self-parent",
            60,
            61,
        ),
    ];
    let mut sorted = spans.clone();
    sort_spans(&mut sorted);
    let order: Vec<&str> = sorted.iter().map(|s| s.name.as_str()).collect();
    assert_eq!(
        order,
        ["orphan", "root", "child-a", "child-b", "self-parent"]
    );
    let tree = build_tree(&spans);
    assert_eq!(tree.len(), 3, "orphan, root and self-parent are roots");
    let root = &tree[1];
    assert_eq!(root.span.name, "root");
    let kids: Vec<&str> = root.children.iter().map(|n| n.span.name.as_str()).collect();
    assert_eq!(kids, ["child-a", "child-b"]);

    let trace = Trace::new("4bf92f3577b34da6a3ce929d0e0e4736", spans);
    assert_eq!(trace.spans[0].name, "orphan");
    assert_eq!(trace.tree().len(), 3);
    let mut kids = trace.children_of("root");
    kids.sort();
    assert_eq!(kids, ["child-a", "child-b"]);
    let s = trace.summary();
    assert_eq!(
        s,
        TraceSummary {
            trace_id: trace.trace_id.clone(),
            root_service_name: Some("svc".into()),
            root_name: Some("orphan".into()),
            start_micros: 5,
            duration_micros: 56,
            span_count: 5,
        }
    );
    let empty = Trace::new("x", vec![]).summary();
    assert_eq!(
        (empty.span_count, empty.root_name, empty.duration_micros),
        (0, None, 0)
    );
    let json = serde_json::to_value(&s).unwrap();
    assert_eq!(json["rootName"], "orphan");
    assert_eq!(json["spanCount"], 5);
}

#[test]
fn span_json_form_roundtrip_and_leniency() {
    let mut s = span(
        "000000000000000b",
        Some("000000000000000a"),
        "op",
        1_000_000,
        1_500_000,
    );
    s.kind = SpanKind::Server;
    s.status = SpanStatus {
        code: StatusCode::Error,
        message: Some("boom".into()),
    };
    s.attributes.insert("n".into(), json!(1));
    s.events.push(sdk::tracing::SpanEvent {
        name: "checkpoint".into(),
        time_micros: 1_200_000,
        attributes: Default::default(),
    });
    s.links.push(sdk::tracing::SpanLink {
        trace_id: "4bf92f3577b34da6a3ce929d0e0e4736".into(),
        span_id: "000000000000000c".into(),
        attributes: Default::default(),
    });
    let v = serde_json::to_value(&s).unwrap();
    assert_eq!(v["startMicros"], 1_000_000);
    assert_eq!(v["endMicros"], 1_500_000);
    assert_eq!(v["durationMicros"], 500_000);
    assert_eq!(v["status"], json!({"code": "error", "message": "boom"}));
    assert_eq!(v["kind"], "server");
    assert_eq!(v["parentSpanId"], "000000000000000a");
    assert_eq!(
        v["events"][0],
        json!({"name": "checkpoint", "timeMicros": 1_200_000, "attributes": {}})
    );
    assert_eq!(v["links"][0]["spanId"], "000000000000000c");
    let back: Span = serde_json::from_value(v).unwrap();
    assert_eq!(back, s);
    let unset = serde_json::to_value(span("000000000000000a", None, "r", 0, 1)).unwrap();
    assert_eq!(unset["status"], json!({"code": "unset"}));
    assert!(unset.get("parentSpanId").is_none());

    let lenient: Span = serde_json::from_value(json!({
        "traceId": "t", "spanId": "s", "name": "n", "serviceName": "svc",
        "startMicros": 2, "endMicros": 3, "durationMicros": 1,
        "kind": "SPAN_KIND_CLIENT", "status": "ok"
    }))
    .unwrap();
    assert_eq!(lenient.kind, SpanKind::Client);
    assert_eq!(lenient.status.code, StatusCode::Ok);
    let minimal: Span = serde_json::from_value(json!({
        "traceId": "t", "spanId": "s", "name": "n", "serviceName": "svc",
        "startMicros": 2, "endMicros": 2, "durationMicros": 0
    }))
    .unwrap();
    assert_eq!(
        (minimal.kind, minimal.status.code),
        (SpanKind::Internal, StatusCode::Unset)
    );
    assert!(serde_json::from_value::<Span>(json!({"traceId": "t"})).is_err());
    assert!(serde_json::from_value::<Span>(json!({
        "traceId": "t", "spanId": "s", "name": "n", "serviceName": "svc",
        "startMicros": 2, "endMicros": 2, "durationMicros": 0, "status": 5
    }))
    .is_err());
    let trace: Trace = serde_json::from_value(json!({"traceId": "t"})).unwrap();
    assert!(trace.spans.is_empty());
    let b = serde_json::to_value(span("000000000000000b", None, "b", 5, 6)).unwrap();
    let a = serde_json::to_value(span("000000000000000a", None, "a", 1, 2)).unwrap();
    let trace: Trace = serde_json::from_value(json!({"traceId": "t", "spans": [b, a]})).unwrap();
    assert_eq!(trace.spans[0].name, "a", "spans are sorted on input");
}

